export function slideImageSize(src) {
  const at = String(src).lastIndexOf('/');
  const deck = SLIDE_IMAGE_SIZES[String(src).slice('/figures/'.length, at)];
  return (deck && deck[String(src).slice(at + 1)]) || null;
}
